	/** 
	 * jumpstart the process by instantiating2 Tag
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		tagId = TagService.getTagInstance()
		.createTag( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		TagService.getTagInstance()
				.createTag( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.tagSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Tag : " + successValue.getTagId());
							  if (successValue.getTagId().equals(tagId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfTagList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Tag test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on tag consumed")
					);
			subscriber.tagSubscribe( tagId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Tag : " + successValue.getTagId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfTagList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on tag for tagId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Tag. 
	 */
	protected Tag read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Tag" );

		Tag entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Tag with primary key" );
		msg.append( tagId );
		
		TagFetchOneSummary fetchOneSummary = new TagFetchOneSummary( tagId );

		try {
			entity = TagService.getTagInstance().getTag( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Tag " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Tag.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Tag." );

		StringBuilder msg = new StringBuilder( "Failed to update a Tag : " );        
		Tag entity = read();
		UpdateTagCommand command = generateUpdateCommand();
		command.setTagId(entity.getTagId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Tag." );

			// for use later on...
			tagId = entity.getTagId();

			TagService proxy = TagService.getTagInstance();  

			proxy.updateTag( command ).get();

			LOGGER.info( "-- Successfully saved Tag - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + tagId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Tag.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Tag." );

		Tag entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Tag with id " + tagId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Tag with id " + tagId );

			throw e;
		}

		try{
			TagService.getTagInstance().delete( new DeleteTagCommand( entity.getTagId() ) ).get();
			LOGGER.info( "-- Successfully deleted Tag with id " + tagId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Tag with id " + tagId );

			throw e;
		}
	}

	/**
	 * get all Tags.
	 */
	protected List<Tag> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Tags:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Tag : " );        
		List<Tag> collection  = new ArrayList<>();

		try {
			// call the static get method on the TagService
			collection = TagService.getTagInstance().getAllTag();
			assertNotNull( collection, "An Empty collection of Tag was incorrectly returned.");
			
			// Now print out the values
			Tag entity = null;            
			Iterator<Tag> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getTagId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

